begin;
-- La fonction est gérée uniquement par l’administrateur.
do $$begin if to_regprocedure('public.workshop_save_signature_before40(text,text,integer)') is null then alter function public.workshop_save_signature(text,text,integer) rename to workshop_save_signature_before40;end if;end $$;
revoke all on function public.workshop_save_signature_before40(text,text,integer) from public,anon,authenticated;
create or replace function public.workshop_save_signature(p_signature text,p_job_title text,p_version integer) returns void language plpgsql security definer set search_path='' as $$
declare a jsonb;stored text;effective text;begin a:=workshop_private.actor();select job_title into stored from public.workshop_signatures where user_id=auth.uid();select coalesce(nullif(stored,''),team,'') into effective from public.workshop_staff where id=a->>'self';if not coalesce((a->>'admin')::boolean,false) then if p_job_title is distinct from coalesce(effective,'') then raise exception 'La fonction est modifiable uniquement par l’administrateur.' using errcode='42501';end if;p_job_title:=coalesce(stored,'');end if;perform public.workshop_save_signature_before40(p_signature,p_job_title,p_version);end $$;
create or replace function public.workshop_admin_job(p_staff text,p_job text default null,p_version integer default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;uid uuid;t text;r public.workshop_signatures%rowtype;begin a:=workshop_private.actor();if not coalesce((a->>'admin')::boolean,false) then raise exception 'Administrateur uniquement.' using errcode='42501';end if;select u.id,s.team into uid,t from public.workshop_staff s join auth.users u on lower(u.email)=s.email where s.id=p_staff and s.active and s.role<>'guest';if uid is null then raise exception 'Crée d’abord le compte de ce collaborateur.';end if;perform pg_advisory_xact_lock(hashtextextended('signature:'||uid::text,0));select * into r from public.workshop_signatures where user_id=uid;if p_job is not null then if length(trim(p_job))>100 or p_version is distinct from coalesce(r.version,0) then raise exception 'Fonction trop longue ou profil modifié ailleurs. Actualise.';end if;insert into public.workshop_signatures(user_id,job_title) values(uid,trim(p_job)) on conflict(user_id) do update set job_title=excluded.job_title,version=workshop_signatures.version+1,updated_at=now();select * into r from public.workshop_signatures where user_id=uid;end if;return jsonb_build_object('job_title',coalesce(nullif(r.job_title,''),t,''),'version',coalesce(r.version,0));end $$;
alter table public.workshop_reports add column if not exists certified_at timestamptz;
alter table public.workshop_reports add column if not exists certified_name text;
create or replace function workshop_private.invalidate_report_signature() returns trigger language plpgsql set search_path='' as $$
begin if (new.version,new.registration,new.notes,new.before_intervention,new.client_notified) is distinct from (old.version,old.registration,old.notes,old.before_intervention,old.client_notified) then new.author_signature:=null;new.signed_at:=null;new.certified_at:=null;new.certified_name:=null;end if;return new;end $$;
do $$begin
 if to_regprocedure('public.workshop_create_report_before40(uuid,text,text,jsonb,boolean,boolean,boolean)') is null then alter function public.workshop_create_report(uuid,text,text,jsonb,boolean,boolean,boolean) rename to workshop_create_report_before40;end if;
 if to_regprocedure('public.workshop_update_report_before40(uuid,integer,text,text,jsonb,boolean,boolean,boolean)') is null then alter function public.workshop_update_report(uuid,integer,text,text,jsonb,boolean,boolean,boolean) rename to workshop_update_report_before40;end if;
 if to_regprocedure('public.workshop_get_report_before40(uuid)') is null then alter function public.workshop_get_report(uuid) rename to workshop_get_report_before40;end if;
end $$;
create or replace function workshop_private.certify_report(p_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare a jsonb;person text;begin a:=workshop_private.actor();perform workshop_private.sign_report(p_id,exists(select 1 from public.workshop_reports r join public.workshop_signatures s on s.user_id=r.author_id where r.id=p_id and r.author_id=auth.uid() and s.signature is not null));select name into person from public.workshop_staff where id=a->>'self';update public.workshop_reports set certified_at=now(),certified_name=coalesce(person,a->>'user') where id=p_id;end $$;
revoke all on function workshop_private.certify_report(uuid) from public,anon,authenticated;
create or replace function public.workshop_create_report(p_id uuid,p_registration text,p_notes text,p_photos jsonb,p_before_intervention boolean,p_client_notified boolean,p_certified boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;r public.workshop_reports%rowtype;ex boolean;begin perform workshop_private.actor();if p_certified is distinct from true or p_client_notified is null then raise exception 'Coche : Je certifie l’exactitude des informations saisies.';end if;perform pg_advisory_xact_lock(hashtextextended('report-location:'||p_id::text,0));select * into r from public.workshop_reports where id=p_id;ex:=found;if ex and (r.client_notified is distinct from p_client_notified or r.certified_at is null) then raise exception 'Signalement déjà enregistré avec un autre contexte.';end if;result:=public.workshop_create_report(p_id,p_registration,p_notes,p_photos,p_before_intervention);if not ex then update public.workshop_reports set client_notified=p_client_notified where id=p_id;perform workshop_private.certify_report(p_id);end if;return result;end $$;
create or replace function public.workshop_update_report(p_id uuid,p_version integer,p_registration text,p_notes text,p_photos jsonb,p_before_intervention boolean,p_client_notified boolean,p_certified boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;begin perform workshop_private.actor();if p_certified is distinct from true or p_client_notified is null then raise exception 'Coche : Je certifie l’exactitude des informations saisies.';end if;result:=public.workshop_update_report(p_id,p_version,p_registration,p_notes,p_photos,p_before_intervention);update public.workshop_reports set client_notified=p_client_notified where id=p_id;perform workshop_private.certify_report(p_id);return result;end $$;
create or replace function public.workshop_get_report(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
begin return public.workshop_get_report_before40(p_id)||(select jsonb_build_object('certified_at',certified_at,'certified_name',certified_name) from public.workshop_reports where id=p_id);end $$;
-- Fermer toutes les anciennes entrées de création/édition sans certification.
do $$declare f record;begin for f in select oid::regprocedure sig from pg_proc where pronamespace='public'::regnamespace and (proname in ('workshop_create_report','workshop_update_report') or proname in ('workshop_create_report_before40','workshop_update_report_before40','workshop_get_report_before40')) loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);end loop;end $$;
revoke all on function public.workshop_save_signature(text,text,integer),public.workshop_admin_job(text,text,integer),public.workshop_get_report(uuid) from public,anon,authenticated;
grant execute on function public.workshop_save_signature(text,text,integer),public.workshop_admin_job(text,text,integer),public.workshop_create_report(uuid,text,text,jsonb,boolean,boolean,boolean),public.workshop_update_report(uuid,integer,text,text,jsonb,boolean,boolean,boolean),public.workshop_get_report(uuid) to authenticated;
notify pgrst,'reload schema';commit;
